CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE OR REPLACE FUNCTION public.check_sos_pin(_user uuid,_pin text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE s public.user_security; valid boolean; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Service only'; END IF; SELECT * INTO s FROM public.user_security WHERE user_id=_user FOR UPDATE; IF s.user_id IS NULL OR s.locked_until>now() THEN RETURN false; END IF; IF s.locked_until IS NOT NULL AND s.locked_until<=now() THEN s.attempts:=0; END IF; valid:=s.pin_hash=extensions.crypt(_pin,s.pin_hash); UPDATE public.user_security SET attempts=CASE WHEN valid THEN 0 ELSE s.attempts+1 END, locked_until=CASE WHEN NOT valid AND s.attempts+1>=5 THEN now()+interval '15 minutes' ELSE NULL END WHERE user_id=_user; RETURN valid; END $$;
REVOKE ALL ON FUNCTION public.check_sos_pin(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.check_sos_pin(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.set_sos_pin(_user uuid,_pin text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.role()<>'service_role' OR _pin !~ '^\d{6}$' THEN RAISE EXCEPTION 'Service and valid PIN required'; END IF; INSERT INTO public.user_security(user_id,pin_hash) VALUES(_user,extensions.crypt(_pin,extensions.gen_salt('bf',10))) ON CONFLICT(user_id) DO UPDATE SET pin_hash=excluded.pin_hash,attempts=0,locked_until=NULL; END $$;
REVOKE ALL ON FUNCTION public.set_sos_pin(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.set_sos_pin(uuid,text) TO service_role;